mapper.select:
SELECT DISTINCT M.MENU_ID , M.MENU_NAME , M.MENU_TYPE , M.URL , M.PARENT_MENU_ID , M.SORT_ORDER , M.DATA_STATUS , M.CREATED_BY , M.CREATED_AT , M.UPDATED_BY , M.UPDATED_AT FROM TB_MENU M WHERE TRUE
AND M.MENU_ID = #{menuId}
AND M.MENU_ID IN
#{menuId}
AND M.MENU_NAME LIKE CONCAT('%', #{menuName}, '%')
AND EXISTS ( SELECT 1 FROM TB_MENU_AUTHORITY MA WHERE MA.MENU_ID = M.MENU_ID AND MA.AUTHORITY_ROLE IN
#{authorityRole}
)
AND M.MENU_TYPE = #{menuType}
AND M.DATA_STATUS = #{dataStatus}
ORDER BY M.SORT_ORDER

SELECT M.MENU_ID , M.MENU_NAME , M.MENU_TYPE , M.URL , M.PARENT_MENU_ID , M.SORT_ORDER , M.DATA_STATUS , M.CREATED_BY , M.CREATED_AT , M.UPDATED_BY , M.UPDATED_AT FROM TB_MENU M WHERE TRUE
AND M.MENU_ID = #{menuId}
AND M.DATA_STATUS = #{dataStatus}

WITH RECURSIVE MENU_INFO AS ( SELECT M.MENU_ID , M.MENU_NAME , M.MENU_TYPE , M.URL , M.PARENT_MENU_ID , M.SORT_ORDER , NOT EXISTS ( SELECT 1 FROM TB_MENU_AUTHORITY WMA WHERE WMA.MENU_ID = M.MENU_ID AND WMA.AUTHORITY_TYPE = 'WRITE' AND WMA.AUTHORITY_ROLE IN
#{authorityRole}
) AS READONLY FROM TB_MENU M INNER JOIN TB_MENU_AUTHORITY MA ON M.MENU_ID = MA.MENU_ID WHERE MA.AUTHORITY_ROLE IN
#{authorityRole}
AND M.DATA_STATUS = 'ENABLED'
UNION
SELECT P.MENU_ID , P.MENU_NAME , P.MENU_TYPE , P.URL , P.PARENT_MENU_ID , P.SORT_ORDER , NOT EXISTS ( SELECT 1 FROM TB_MENU_AUTHORITY WMA WHERE WMA.MENU_ID = P.MENU_ID AND WMA.AUTHORITY_TYPE = 'WRITE' AND WMA.AUTHORITY_ROLE IN
#{authorityRole}
) AS READONLY FROM TB_MENU P INNER JOIN MENU_INFO C ON P.MENU_ID = C.PARENT_MENU_ID WHERE P.DATA_STATUS = 'ENABLED' ) SELECT DISTINCT MENU_ID , MENU_NAME , MENU_TYPE , URL , PARENT_MENU_ID , SORT_ORDER , READONLY FROM MENU_INFO ORDER BY SORT_ORDER

mapper.insert:
INSERT INTO TB_MENU (
    MENU_ID
  , MENU_NAME
  , MENU_TYPE
  , URL
  , PARENT_MENU_ID
  , SORT_ORDER
  , DATA_STATUS
  , CREATED_BY
  , UPDATED_BY
) VALUES (
    #{menuId}
  , #{menuName}
  , #{menuType}
  , #{url}
  , #{parentMenuId}
  , #{sortOrder}
  , #{dataStatus}
  , #{author}
  , #{author}
)

mapper.update:
UPDATE TB_MENU
   SET MENU_NAME   = #{menuName}
     , DATA_STATUS = #{dataStatus}
     , UPDATED_BY  = #{author}
     , UPDATED_AT  = NOW()
 WHERE MENU_ID     = #{menuId}
